idx = device.find(description="Search", clickable=True)
if idx is None:
    idx = device.find(description="Search")  # tolerate toolbars that drop the clickable flag
if idx is None:
    raise LookupError("Markor: toolbar 'Search' affordance not found (description='Search', clickable=True)")
device.click(index=idx)
device.settle(0.5)
if device.find(hint="Search", editable=True) is None:
    raise LookupError("Markor: tapping 'Search' did not open the search screen")
